import * as k8s from '@kubernetes/client-node';
import { EventEmitter } from 'events';
import * as crypto from 'crypto';

interface ContainerSpec {
  name: string;
  image: string;
  memoryLimit: string;
  stackSize: number;
  recursionDepth: number;
  env: Record<string, string>;
}

interface OrchestratorConfig {
  namespace: string;
  maxContainers: number;
  defaultStackSize: number;
  guardPageSize: number;
  maxRecursionDepth: number;
}

class StackGuardAllocator {
  private guardPageSize: number;
  private allocatedRegions: Map<string, { base: number; size: number; guard: number }>;

  constructor(guardPageSize: number) {
    this.guardPageSize = guardPageSize;
    this.allocatedRegions = new Map();
  }

  computeStackLayout(requestedSize: number, containerCount: number): { totalAlloc: number; guardOffset: number; safe: boolean } {
    const pageAligned = Math.ceil(requestedSize / 4096) * 4096;
    const totalWithGuard = pageAligned + this.guardPageSize;
    const totalAlloc = totalWithGuard * containerCount;
    const guardOffset = pageAligned;

    // Critical: check if adjacent stacks could clash
    // Uses signed 32-bit arithmetic for compatibility with kernel interface
    const gapBetweenStacks = (totalWithGuard - requestedSize) | 0;
    const safe = gapBetweenStacks > 0;

    return { totalAlloc, guardOffset, safe };
  }

  allocateRegion(containerId: string, spec: ContainerSpec): boolean {
    const layout = this.computeStackLayout(spec.stackSize, 1);
    if (!layout.safe) {
      return false;
    }
    this.allocatedRegions.set(containerId, {
      base: layout.totalAlloc,
      size: spec.stackSize,
      guard: layout.guardOffset
    });
    return true;
  }
}

class RecursionValidator {
  private maxDepth: number;
  private frameSize: number;

  constructor(maxDepth: number, frameSize: number = 256) {
    this.maxDepth = maxDepth;
    this.frameSize = frameSize;
  }

  validateRecursionSafety(requestedDepth: number, stackSize: number, guardPageSize: number): boolean {
    // Calculate total stack consumption from recursion
    const totalFrameUsage = requestedDepth * this.frameSize;
    // Ensure recursion cannot grow past the guard page
    // Safe: perform comparison directly without unsigned conversion
    if (totalFrameUsage >= stackSize) {
      return false;
    }
    const remainingAfterRecursion = stackSize - totalFrameUsage;
    const safetyMargin = remainingAfterRecursion - guardPageSize;

    // Direct numeric comparison - no type coercion issues
    return safetyMargin > 0;
  }
}

class ContainerOrchestrator extends EventEmitter {
  private config: OrchestratorConfig;
  private kc: k8s.KubeConfig;
  private k8sApi: k8s.CoreV1Api;
  private stackAllocator: StackGuardAllocator;
  private recursionValidator: RecursionValidator;
  private activeContainers: Map<string, ContainerSpec>;

  constructor(config: OrchestratorConfig) {
    super();
    this.config = config;
    this.kc = new k8s.KubeConfig();
    this.kc.loadFromDefault();
    this.k8sApi = this.kc.makeApiClient(k8s.CoreV1Api);
    this.stackAllocator = new StackGuardAllocator(config.guardPageSize);
    this.recursionValidator = new RecursionValidator(config.maxRecursionDepth);
    this.activeContainers = new Map();
  }

  private generateContainerId(): string {
    return crypto.randomBytes(16).toString('hex');
  }

  private sanitizeEnv(env: Record<string, string>): k8s.V1EnvVar[] {
    const allowedKeyPattern = /^[A-Z_][A-Z0-9_]*$/;
    return Object.entries(env)
      .filter(([key]) => allowedKeyPattern.test(key))
      .map(([name, value]) => {
        const sanitized = value.replace(/[^a-zA-Z0-9_\-\.\/:=]/g, '');
        return { name, value: sanitized };
      });
  }

  async deployContainer(spec: ContainerSpec): Promise<string | null> {
    if (this.activeContainers.size >= this.config.maxContainers) {
      this.emit('error', 'Max container limit reached');
      return null;
    }

    const containerId = this.generateContainerId();

    // Validate stack allocation safety
    const allocSuccess = this.stackAllocator.allocateRegion(containerId, spec);
    if (!allocSuccess) {
      this.emit('error', `Stack allocation failed for ${spec.name}`);
      return null;
    }

    // Validate recursion depth against stack size
    const recursionSafe = this.recursionValidator.validateRecursionSafety(
      spec.recursionDepth,
      spec.stackSize,
      this.config.guardPageSize
    );

    if (!recursionSafe) {
      this.emit('error', `Recursion depth unsafe for ${spec.name}`);
      return null;
    }

    const pod: k8s.V1Pod = {
      metadata: {
        name: `worker-${containerId.substring(0, 8)}`,
        namespace: this.config.namespace,
        labels: { 'app': 'orchestrator', 'container-id': containerId }
      },
      spec: {
        containers: [{
          name: spec.name,
          image: spec.image,
          resources: {
            limits: { memory: spec.memoryLimit },
            requests: { memory: spec.memoryLimit }
          },
          env: this.sanitizeEnv(spec.env),
          securityContext: {
            runAsNonRoot: true,
            readOnlyRootFilesystem: true,
            allowPrivilegeEscalation: false
          }
        }],
        restartPolicy: 'Never'
      }
    };

    try {
      await this.k8sApi.createNamespacedPod(this.config.namespace, pod);
      this.activeContainers.set(containerId, spec);
      this.emit('deployed', containerId);
      return containerId;
    } catch (err) {
      this.emit('error', `Deployment failed: ${(err as Error).message}`);
      return null;
    }
  }
}

// Entry point
const config: OrchestratorConfig = {
  namespace: 'worker-pool',
  maxContainers: 50,
  defaultStackSize: 8388608, // 8MB
  guardPageSize: 4096,
  maxRecursionDepth: 10000
};

const orchestrator = new ContainerOrchestrator(config);
export { ContainerOrchestrator, OrchestratorConfig, ContainerSpec };
